INSERT INTO genres(id,name,description) VALUES
(1,'Rock','Guitar-driven music with strong rhythm and amplified instrumentation.'),(2,'Pop','Accessible contemporary songs with catchy melodies.'),(3,'Metal','Heavy guitar riffs, powerful drums and aggressive textures.'),(4,'Alternative','Experimental and modern rock-oriented music.'),(5,'Indie','Independent-leaning music with distinctive production.'),(6,'Electronic','Music built around synthesizers, samples and electronic production.'),(7,'Hip Hop','Rhythm-focused music centered on beats and vocal flow.'),(8,'Jazz','Improvisation-oriented music with rich harmonic structures.'),(9,'R&B','Soulful rhythm and blues with expressive vocals.'),(10,'Punk','Fast, direct and energetic guitar music.');
INSERT INTO artists(id,name,country,debut_year,bio) VALUES
(1,'Arctic Monkeys','United Kingdom',2002,'English rock band known for sharp songwriting and rhythmic guitar arrangements.'),(2,'Muse','United Kingdom',1994,'Rock band recognized for dramatic arrangements and electronic textures.'),(3,'Linkin Park','United States',1996,'Alternative rock band blending rock, electronic and hip-hop elements.'),(4,'Paramore','United States',2004,'Alternative rock band with energetic vocals and guitar-driven arrangements.'),(5,'Foo Fighters','United States',1994,'Rock band founded by Dave Grohl with a strong live-oriented sound.'),(6,'Bring Me The Horizon','United Kingdom',2004,'Band known for evolving from metalcore into electronic and alternative styles.'),(7,'The Weeknd','Canada',2010,'Contemporary R&B artist with atmospheric electronic production.'),(8,'Daft Punk','France',1993,'Electronic duo influential in house, funk and dance music.'),(9,'Kendrick Lamar','United States',2003,'Hip-hop artist known for detailed storytelling and layered production.'),(10,'Green Day','United States',1987,'Punk rock band known for melodic and high-energy songwriting.'),(11,'Radiohead','United Kingdom',1985,'Alternative rock band known for experimental arrangements.'),(12,'Nirvana','United States',1987,'Grunge band that shaped alternative rock in the 1990s.');
